function translate(language, key) {
  const locale = language === 'ar' ? 'ar' : 'en';
  return messages[locale][key] || messages.en[key] || (locale === 'ar' ? (arText[key] || key) : key);
}

function localizeHtml(html, language) {
  if (language !== 'ar' || typeof html !== 'string') return html;
  let output = html.replace(/>([^<>]+)</g, (whole, raw) => {
    const trimmed = raw.trim();
    const translated = arText[trimmed];
    if (!translated) return whole;
    const start = raw.match(/^\s*/)?.[0] || '';
    const end = raw.match(/\s*$/)?.[0] || '';
    return `>${start}${translated}${end}<`;
  });
  output = output.replace(/\b(placeholder|aria-label|title|data-confirm)=(['"])(.*?)\2/g, (whole, attr, quote, value) => {
    const translated = arText[value];
    return translated ? `${attr}=${quote}${translated}${quote}` : whole;
  });
  return output;
}

module.exports = { translate, localizeHtml, arText };
